import { type Column, type Table, getTableColumns } from "drizzle-orm";
import { type ColumnMap, type ColumnSpec, defineColumnMap } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";
import { isDev } from "@/registry/default/components/data-grid-server-query/data-grid-server-query-sdk";

export type ColumnsFromDrizzleTableOptions<Id extends string> = {
  /** The columns the client may see, by the table's property names. Required: no helper maps a whole table. */
  pick: readonly Id[];
  /** Per-column changes to the generated spec. */
  overrides?: { [K in Id]?: Partial<ColumnSpec> };
  /** Columns that order rows when the table has no single-column primary key. */
  tieBreaker?: readonly Id[];
};

const SMALL = new Set(["PgSmallInt", "PgSmallSerial"]);
const INT53 = new Set(["PgBigInt53", "PgBigSerial53", "SQLiteInteger"]);
const FLOAT = new Set(["PgReal", "PgDoublePrecision", "SQLiteReal"]);

function specFor(id: string, column: Column): ColumnSpec {
  const columnType = column.columnType;
  const base = { required: column.notNull, primaryKey: column.primary, field: id };
  const sqlite = columnType.startsWith("SQLite");
  switch (column.dataType) {
    case "number":
      if (columnType.endsWith("NumericNumber")) return { ...base, type: "number", numeric: "decimal" };
      if (FLOAT.has(columnType)) return { ...base, type: "number", numeric: "float" };
      return { ...base, type: "number", numeric: SMALL.has(columnType) ? "int2" : INT53.has(columnType) ? "int8" : "int4" };
    case "bigint":
      if (columnType.endsWith("NumericBigInt")) return { ...base, type: "number", numeric: "decimal" };
      return { ...base, type: "number", numeric: "int8" };
    case "boolean":
      return { ...base, type: "checkbox" };
    case "date":
      if (columnType === "PgTimestamp") return { ...base, type: "date", time: true, storage: "native" };
      if (sqlite) return { ...base, type: "date", time: true, storage: (column as unknown as { mode?: string }).mode === "timestamp_ms" ? "epoch-ms" : "epoch-s" };
      return { ...base, type: "date" };
    case "string": {
      if (columnType === "PgNumeric" || columnType === "SQLiteNumeric") {
        const scale = (column as unknown as { scale?: number }).scale;
        return { ...base, type: "number", numeric: "decimal", ...(scale === undefined || scale === null ? {} : { scale }) };
      }
      if (columnType === "PgDateString") return { ...base, type: "date" };
      if (columnType === "PgTimestampString") return { ...base, type: "date", time: true, storage: "native" };
      if (columnType === "PgEnumColumn" && column.enumValues) return { ...base, type: "select", native: "enum", choices: [...column.enumValues] };
      if (columnType === "PgUUID") return { ...base, type: "text", native: "uuid" };
      return { ...base, type: "text" };
    }
    default:
      if (isDev()) console.warn(`gridcn query layer: column "${id}" has the type ${columnType}, which the column map reads as text. Override it if that is wrong.`);
      return { ...base, type: "text" };
  }
}

/**
 * Builds the column map of picked Drizzle columns: kinds, nullability, enums, uuids, decimals, and the primary key come
 * from the schema. Adjust one column with `overrides`.
 *
 * @example
 * const columns = columnsFromDrizzleTable(users, { pick: ["id", "name", "tenantId"], overrides: { name: { searchable: true } } });
 */
export function columnsFromDrizzleTable<TTable extends Table, Id extends keyof TTable["_"]["columns"] & string>(table: TTable, options: ColumnsFromDrizzleTableOptions<Id>): ColumnMap<Id> {
  const all = getTableColumns(table) as Record<string, Column>;
  const specs: Record<string, ColumnSpec> = {};
  const primaries = options.pick.filter((id) => all[id]?.primary);
  const overrides = options.overrides as Record<string, Partial<ColumnSpec>> | undefined;
  for (const id of options.pick) {
    const column = Object.hasOwn(all, id) ? all[id] : undefined;
    if (!column) throw new Error(`columnsFromDrizzleTable: the table has no column "${id}"`);
    const generated = specFor(id, column);
    if (primaries.length > 1) generated.primaryKey = false;
    specs[id] = { ...generated, ...(overrides && Object.hasOwn(overrides, id) ? overrides[id] : {}) };
  }
  const tieBreaker = options.tieBreaker ?? (primaries.length > 1 ? primaries : undefined);
  return defineColumnMap(specs, tieBreaker ? { tieBreaker } : {}) as unknown as ColumnMap<Id>;
}

import { type Column, SQL, type Table, getTableColumns, sql } from "drizzle-orm";
import type { AdapterCapabilities, ColumnMap, GridQuery, QueryLimits, RowCountMode, RowScope } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";
import {
  type CustomHandler,
  type PlanColumn,
  type SqlAlgebra,
  assertCustomOperatorHandlers,
  createGridQuery,
  createSqlRenderer,
  mapOf,
} from "@/registry/default/components/data-grid-server-query/data-grid-server-query-sdk";

type Rows = Record<string, unknown>[];
type Builder = PromiseLike<Rows> & {
  from(table: Table): Builder;
  where(condition: SQL): Builder;
  orderBy(...order: SQL[]): Builder;
  groupBy(...group: SQL[]): Builder;
  limit(count: number): Builder;
  offset(count: number): Builder;
};

/** A Drizzle database of any driver. */
export type DrizzleDatabase = { select: (...args: never[]) => unknown };

export type DrizzleGridQueryOptions<TContext = never> = {
  db: DrizzleDatabase;
  table: Table;
  columns: ColumnMap;
  /** Equalities on mapped columns that every query ANDs in. Needs `context` on every call. */
  rowScope?: RowScope<TContext>;
  /** When a rows request also counts the result. Default `"firstBlock"`. */
  rowCount?: RowCountMode;
  limits?: QueryLimits;
  /** IANA zone or fixed offset of day filters on `time` columns. Default `"UTC"`. */
  timeZone?: string;
  /** Handlers for the custom operators the column map declares; each returns a Drizzle `sql` fragment and must bind `value` through it. */
  customOperators?: Record<string, (ctx: { column: PlanColumn; value: unknown }) => SQL>;
};

/** Reads and counts rows with Drizzle, from the column map and a request body. */
export function createDrizzleGridQuery<TRow = Record<string, unknown>, TContext = never>(options: DrizzleGridQueryOptions<TContext>): GridQuery<TRow, TContext, SQL, SQL> {
  const { db, table, columns } = options;
  const tableColumns = getTableColumns(table) as Record<string, Column>;
  const first = Object.values(tableColumns)[0];
  const dialect = first?.columnType.startsWith("SQLite") ? "sqlite" : "pg";
  const physical = new Map<string, Column>();
  for (const column of mapOf(columns).byId.values()) {
    const found = Object.hasOwn(tableColumns, column.field) ? tableColumns[column.field] : undefined;
    if (!found) throw new Error(`createDrizzleGridQuery: the table has no column "${column.field}" for "${column.id}"`);
    physical.set(column.id, found);
  }
  assertCustomOperatorHandlers(columns, options.customOperators);
  const algebra: SqlAlgebra<SQL> = {
    dialect,
    raw: (text) => sql.raw(text),
    param: (value) => sql`${value}`,
    column: (column) => sql`${physical.get(column.id)!}`,
    cat: (...parts) => sql.join(parts, sql.raw("")),
    native: (value) => {
      if (!(value instanceof SQL)) throw new Error("customOperators: a handler must return a Drizzle sql fragment");
      return value;
    },
  };
  const renderer = createSqlRenderer(algebra, new Map(Object.entries(options.customOperators ?? {})) as ReadonlyMap<string, CustomHandler>);
  const selectFrom = (fields: Record<string, unknown>) => (db as unknown as { select(fields: Record<string, unknown>): { from(table: Table): Builder } }).select(fields).from(table);
  const capabilities: AdapterCapabilities = {
    caseInsensitiveText: dialect === "pg" ? "collation" : "ascii",
    likeEscape: true,
    literalAsterisk: true,
    nullsLast: "native",
    aggregates: true,
    groupBy: true,
    localDayGrouping: dialect === "pg",
  };

  return createGridQuery<TRow, TContext, SQL, SQL>({
    columns,
    rowScope: options.rowScope,
    rowCount: options.rowCount,
    limits: options.limits,
    timeZone: options.timeZone,
    executor: {
      capabilities,
      where: (plan) => renderer.predicate(plan.where),
      orderBy: (plan) => renderer.orderBy(plan.orderBy),
      selectRows: (plan, page) => {
        const fields = Object.fromEntries(plan.projection.map((column) => [column.id, physical.get(column.id)!]));
        return Promise.resolve(selectFrom(fields).where(renderer.predicate(plan.where)).orderBy(renderer.orderBy(plan.orderBy)).limit(page.limit).offset(page.offset));
      },
      countRows: async (plan) => {
        const rows = await selectFrom({ n: sql`count(*)` }).where(renderer.predicate(plan.where));
        return rows[0]?.["n"];
      },
      selectValues: (plan, { limit }) => {
        const { key, value } = renderer.valueKey(plan.column, options.timeZone ?? "UTC");
        return Promise.resolve(
          selectFrom({ value, count: sql`count(*)` })
            .where(renderer.valuesFilter(plan, options.timeZone ?? "UTC"))
            .groupBy(key)
            .orderBy(sql`count(*) DESC`, sql`${value} ASC`)
            .limit(limit),
        ) as Promise<{ value: unknown; count: unknown }[]>;
      },
      aggregate: async (plan) => {
        const fields = Object.fromEntries(plan.columns.map(({ column, reducer }, index) => [`c${index}`, renderer.aggregate(column, reducer)]));
        const rows = await selectFrom(fields).where(renderer.predicate(plan.where));
        const row = rows[0] ?? {};
        return Object.fromEntries(plan.columns.map(({ column }, index) => [column.id, row[`c${index}`]]));
      },
    },
  });
}
